<script setup lang="ts">
import AppForm from './AppForm.vue';
import FormInput from './FormInput.vue';
import FormSelect from './FormSelect.vue';
import FormTextarea from './FormTextarea.vue';
import { notify, useFeedback } from '../services/feedback';
import { computed, onBeforeUnmount, ref, watch, defineAsyncComponent, useId } from 'vue';
import { Camera, Crosshair, MapPin, Check, Send, X, TriangleAlert, Move } from '@lucide/vue';
import { api, native } from '../services/api'; import { capturePhoto, compressPhoto, currentLocation } from '../services/mediaService';
import type { Category, Department, Hazard, GPS, Point, Severity } from '../types';
import HazardIcon from './HazardIcon.vue';
import municipality from '../config/municipality.json';
import ConfirmDialog from './ConfirmDialog.vue';
import Modal from './Modal.vue';
import { municipalSettings } from '../services/municipalSettings';
const HazardMap = defineAsyncComponent(() => import('./HazardMap.vue'));
const props = defineProps<{ categories: Category[]; departments?: Department[]; demo: boolean; assistanceNeeded?: boolean }>(); const emit = defineEmits<{ created: [report?: Hazard]; close: [] }>(); const formId = useId();
const category = ref('');
watch(() => props.categories, items => { if (!items.some(item => item.id === category.value)) category.value = ''; }, { immediate: true }); const files = ref<File[]>([]); const previews = ref<string[]>([]); const fileInput = ref<InstanceType<typeof FormInput>>();
const gps = ref<GPS>(); const point = ref<Point>(); const showMap = ref(false); const adjusting = ref(false); const confirmed = ref(false); const locating = ref(false);
const title = ref(''); const description = ref(''); const barangay = ref(''); const address = ref(''); const severity = ref<Severity>(props.assistanceNeeded ? 'critical' : 'moderate');
const busy = ref(false); const processing = ref(false); const error = ref(''); const locationError = ref('');
const nearby = ref<{ id: string; reference_number: string; title: string; distance: number }[]>([]); const checked = ref(false); const forceNew = ref(false);
const outsideBasista = computed(() => point.value && (point.value.longitude < municipality.bounds[0]! || point.value.longitude > municipality.bounds[2]! || point.value.latitude < municipality.bounds[1]! || point.value.latitude > municipality.bounds[3]!));
const occurredAt = ref(''); const injuries = ref<'unknown' | 'yes' | 'no'>('unknown'); const peopleAffected = ref<number | ''>('');
const phone = computed(() => municipalSettings.value.hotlines[0]?.number || import.meta.env.VITE_EMERGENCY_PHONE); const pendingSubmit = ref(false);
const source = computed(() => !gps.value ? 'manual' : point.value && Math.abs(point.value.latitude - gps.value.latitude) < 0.000001 && Math.abs(point.value.longitude - gps.value.longitude) < 0.000001 ? 'gps' : 'gps_adjusted');
watch([point, category], () => { confirmed.value = false; checked.value = false; nearby.value = []; forceNew.value = false; });
watch(files, value => { previews.value.forEach(URL.revokeObjectURL); previews.value = value.map(URL.createObjectURL); });
onBeforeUnmount(() => previews.value.forEach(URL.revokeObjectURL));
useFeedback([error, locationError], []);
function pick(p: Point) { point.value = p; }
async function locate() { locating.value = true; locationError.value = ''; try { gps.value = await currentLocation(); pick({ latitude: gps.value.latitude, longitude: gps.value.longitude }); showMap.value = true; adjusting.value = false; notify('Current location found. Check the pin and confirm the hazard location.', 'info'); } catch (e) { locationError.value = (e as Error).message; } finally { locating.value = false; } }
function manual() { showMap.value = true; adjusting.value = true; confirmed.value = false; }
async function addFiles(event: Event) { processing.value = true; error.value = ''; try { const selected = Array.from((event.target as HTMLInputElement).files || []).slice(0, 3 - files.value.length); const compressed = []; for (const file of selected) compressed.push(await compressPhoto(file)); files.value = [...files.value, ...compressed]; if (compressed.length) notify(`${compressed.length} photo(s) added and resized.`); } catch (e) { error.value = (e as Error).message; } finally { processing.value = false; (event.target as HTMLInputElement).value = ''; } }
async function camera() { if (!native) return fileInput.value?.click(); processing.value = true; error.value = ''; try { files.value = [...files.value, await capturePhoto()].slice(0, 3); notify('Photo added and resized.'); } catch (e) { error.value = (e as Error).message; } finally { processing.value = false; } }
async function submit() {
  error.value = ''; if (props.demo) { error.value = 'This is a read-only preview. Exit preview and sign in to send a real report.'; return; }
  if (!category.value || !files.value.length || !point.value || !confirmed.value) { await send(); return; }
  busy.value = true;
  try { if (!checked.value) { nearby.value = await api(`/api/reports/nearby?category=${category.value}&latitude=${point.value.latitude}&longitude=${point.value.longitude}`); checked.value = true; if (nearby.value.length) { notify('Similar hazards found. Review them before sending a separate report.', 'info'); return; } } if (nearby.value.length && !forceNew.value) { error.value = 'Review the nearby hazards or choose to submit a separate report.'; return; } pendingSubmit.value = true; }
  catch (e) { error.value = (e as Error).message; } finally { busy.value = false; }
}
async function send() {
  busy.value = true; error.value = '';
  try {
    const data = new FormData(); const values = { assistance_needed: props.assistanceNeeded ? '1' : '0', category_id: category.value, title: title.value, description: description.value, address: address.value, barangay: barangay.value, severity: severity.value, ...(point.value ? { selected_latitude: point.value.latitude, selected_longitude: point.value.longitude } : {}), location_source: source.value, location_confirmed: confirmed.value ? '1' : '0', ...(gps.value ? { gps_latitude: gps.value.latitude, gps_longitude: gps.value.longitude, gps_accuracy: gps.value.accuracy } : {}) };
    if (occurredAt.value) data.set('occurred_at', new Date(occurredAt.value).toISOString());
    data.set('injuries', injuries.value);
    if (peopleAffected.value !== '') data.set('people_affected', String(peopleAffected.value));
    Object.entries(values).forEach(([key, value]) => data.set(key, String(value))); files.value.forEach(file => data.append('photos[]', file));
    const result = await api<{ data: Hazard }>('/api/reports', { method: 'POST', body: data }); pendingSubmit.value = false; emit('created', result.data);
  } catch (e) { pendingSubmit.value = false; error.value = (e as Error).message; } finally { busy.value = false; }
}
async function confirmDuplicate(id: string) { busy.value = true; error.value = ''; try { await api(`/api/reports/${id}/confirm`, { method: 'POST' }); emit('created'); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><Modal title="Report a hazard" wide @close="emit('close')"><AppForm :id="formId" class="form-body report-form" @submit.prevent="submit">
  <div class="notice emergency"><TriangleAlert :size="22" /><p><strong>Is someone in immediate danger?</strong> Contact emergency services first. An online report is reviewed by staff and does not guarantee immediate dispatch.<a v-if="phone" :href="`tel:${phone}`">Call emergency services</a></p></div>
  <p v-if="assistanceNeeded" class="assistance-banner">Your request for immediate assistance will be highlighted to municipal staff. Continue seeking direct emergency help if possible.</p><div v-if="demo" class="notice neutral">Preview mode · Explore the form. Reports will not be sent.</div>
  <div class="notice neutral privacy-notice"><p><strong>Your evidence stays private.</strong> Original descriptions, exact locations and photos are available to you and authorized municipal administrators. Published news uses separately reviewed incident details and may credit your display name. Contact information stays private.</p></div>
  <fieldset><legend><span class="step">1</span> What happened?</legend><p class="filipino-help" lang="fil">Piliin ang uri ng insidente o panganib.</p><div class="category-grid"><button v-for="item in categories" :key="item.id" type="button" class="category-choice" :class="{ chosen: category === item.id }" :aria-pressed="category === item.id" @click="category = item.id"><HazardIcon :category="item.id" /><span>{{ item.name }}</span></button></div></fieldset>
  <p v-if="category" class="notice neutral report-routing" role="status">Responsible office: <strong>{{ departments?.find(d => d.id === categories.find(c => c.id === category)?.department_id)?.name || 'Municipal response team' }}</strong>. Municipal staff manage routing for this hazard type.</p><fieldset><legend><span class="step">2</span> Add a photo</legend><p class="field-help">Stay at a safe distance. Up to 3 photos, automatically compressed below 1 MB each. Avoid faces, injuries and personal documents. Do not delay calling for help to take photos.</p><div class="photo-row"><div v-for="(url, index) in previews" :key="url" class="photo-preview"><img :src="url" :alt="`Hazard photo ${index + 1}`"><button type="button" :aria-label="`Remove photo ${index + 1}`" @click="files = files.filter((_, i) => i !== index); notify('Photo removed from this draft.', 'info')"><X :size="14" /></button><small>{{ Math.round(files[index]!.size / 1024) }} KB</small></div><button v-if="files.length < 3" type="button" class="photo-upload" :disabled="processing" @click="camera"><Camera :size="27" /><strong>{{ processing ? 'Compressing…' : 'Take or add photo' }}</strong></button><FormInput ref="fileInput" class="visually-hidden" aria-label="Add hazard photos" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple @change="addFiles" /></div></fieldset>
  <fieldset><legend><span class="step">3</span> Where is the hazard?</legend><p class="filipino-help" lang="fil">Ilagay ang lokasyon ng insidente. Suriin ang pin bago kumpirmahin.</p><div class="location-options"><button type="button" class="location-choice" :disabled="locating" @click="locate"><Crosshair :size="23" /><strong>{{ locating ? 'Finding location…' : 'Use current location' }}</strong><small>Use your phone’s GPS</small></button><button type="button" class="location-choice" @click="manual"><MapPin :size="23" /><strong>Choose location on map</strong><small>Place the pin yourself</small></button></div>
  <template v-if="showMap"><div class="location-heading"><span v-if="gps">GPS accuracy: <strong>±{{ Math.round(gps.accuracy) }} m</strong></span><span v-else>Manual location</span><span class="source-tag">{{ source.replace('_', ' ') }}</span></div><p v-if="gps && gps.accuracy > 100" class="notice emergency">GPS accuracy is low. Please check and adjust the hazard pin.</p><p class="field-help">{{ adjusting ? 'Tap the map or drag the green pin to the hazard. The blue dot is your original GPS.' : 'Is the green pin at the hazard? Confirm it below, or adjust the pin.' }}</p><div class="picker-map"><HazardMap style-selector :pin="point" :gps="gps" :editable="adjusting" @pick="pick" /></div><p v-if="point" class="field-help" role="status">Location selected on the map. Check the pin and confirm it below.</p><p v-if="outsideBasista" class="notice emergency">The selected pin is outside Basista’s reference area. Check the pin and selected barangay before sending.</p><div class="location-actions"><button type="button" class="button secondary" @click="adjusting = true; confirmed = false"><Move :size="16" />Adjust pin</button><button type="button" class="button green" :disabled="!point" @click="confirmed = true; adjusting = false; notify('Hazard location confirmed.')"><Check :size="17" />{{ confirmed ? 'Location confirmed' : 'Confirm location' }}</button></div></template>
  <div class="form-grid"><label>Barangay<FormSelect v-model="barangay" required aria-label="Barangay" aria-describedby="barangay-coverage" name="barangay"><option value="" disabled>Choose a Basista barangay</option><option v-for="name in municipality.barangays" :key="name" :value="name">{{ name }}</option></FormSelect><small id="barangay-coverage">Basista Municipal Hall covers these 13 barangays.</small></label><label>Street or landmark<FormInput v-model="address" required minlength="3" maxlength="200" placeholder="Help responders find the location" name="address" /></label></div></fieldset>
  <fieldset><legend><span class="step">4</span> A few details</legend><p class="filipino-help" lang="fil">Ilarawan ang nakita. Huwag ilagay ang pangalan o personal na detalye ng biktima.</p><div class="form-grid"><label>When did it happen? (optional)<FormInput v-model="occurredAt" type="datetime-local" name="occurred_at" /><span class="field-help">Use your phone?s local time. Leave blank if unknown.</span></label><label>Is anyone injured?<FormSelect v-model="injuries" name="injuries"><option value="unknown">Not sure / Hindi tiyak</option><option value="yes">Yes / May nasugatan</option><option value="no">None observed / Walang nakitang nasugatan</option></FormSelect></label><label>People affected (optional estimate)<FormInput v-model.number="peopleAffected" type="number" min="0" max="1000000" step="1" inputmode="numeric" placeholder="Leave blank if unknown" name="people_affected" /></label></div><label>Report title<FormInput v-model="title" required minlength="5" maxlength="120" placeholder="e.g. Fallen tree blocking Riverside Road" name="title" /></label><label>Description<FormTextarea v-model="description" required minlength="15" maxlength="2000" rows="3" placeholder="What can you see? Is access blocked or is anyone at risk?" name="description"></FormTextarea></label><label>How serious does it appear?<FormSelect v-model="severity" name="severity"><option value="low">Low — minor issue</option><option value="moderate">Moderate — needs attention</option><option value="high">High — significant risk</option><option value="critical">Critical — immediate danger</option></FormSelect></label></fieldset>
  <div v-if="nearby.length" class="duplicate-panel"><h3>Similar hazards nearby</h3><p>Is this the same incident? Confirm it to help avoid duplicate dispatches.</p><div v-for="item in nearby" :key="item.id" class="duplicate"><div><strong>{{ item.title }}</strong><small>{{ Math.round(item.distance) }} m away · {{ item.reference_number }}</small></div><button type="button" class="button secondary" :disabled="busy" @click="confirmDuplicate(item.id)">Same hazard</button></div><label class="checkbox-label"><FormInput v-model="forceNew" type="checkbox" name="force_new" />This is a different hazard; submit a new report.</label></div>
  </AppForm><template #footer><button type="submit" :form="formId" class="button primary full" :disabled="busy || processing"><Send :size="17" />{{ busy ? 'Sending…' : 'Submit hazard report' }}</button><p class="field-help center footer-hint">Keep yourself safe. An app report is not an emergency call. You can track a successfully submitted report in My reports.</p>
</template></Modal><ConfirmDialog v-if="pendingSubmit" title="Submit this hazard report?" message="Your exact location, description and photos will be shared privately with authorized municipal administrators for review. An app submission does not guarantee an emergency dispatch." :busy="busy" confirm-label="Submit report" @close="pendingSubmit = false" @confirm="send" /></template>
